-- FILE: 20261015120000_world.sql
-- Necromancer (class 10) Phase 2 batch 3 (minions, slice 2):
-- Ravage (61027, pet ability), Sacrifice Minion (61028), Harvest
-- (61029) + Harvest aura (61030), Death Pact Ghoul/Skeleton
-- (61031/61032) and Ghoul Frenzy (61033).
-- Generated by tools/generate_phase2_batch3_slice2.py; re-runnable.
--
-- Ravage is learned by the raised minions (creature 846/6412) through
-- `petcreateinfo_spell`; the tethered pet counts as permanent after
-- the class descriptor's permanentSummonPetTypes is set by the module
-- (C++, no SQL column).

DELETE FROM `spell_template` WHERE `entry` IN (61027, 61028, 61029, 61030, 61031, 61032, 61033, 61027);
DELETE FROM `skill_line_ability` WHERE `skill_id` = 700 AND `spell_id` IN (61028, 61029, 61033);
DELETE FROM `petcreateinfo_spell` WHERE `entry` IN (846, 6412);

